\set ON_ERROR_STOP on
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
\ir helpers/auth.sql.inc
select no_plan();
insert into public.profiles(id,display_name,base_currency,timezone)
select id,'Synthetic close','USD','Pacific/Kiritimati' from auth.users where id::text like 'f0050000%';
create function pg_temp.month(n integer default 0) returns date language sql stable as $$select (date_trunc('month',statement_timestamp() at time zone 'Pacific/Kiritimati')+make_interval(months=>n))::date$$;
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('f1230000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into public.budget_periods(id,profile_id,starts_on,ends_on,base_currency)
select pg_temp.id(n+10),'f0050000-0000-4000-8000-000000000001',pg_temp.month(n),(pg_temp.month(n)+interval '1 month -1 day')::date,'USD' from generate_series(-3,1) n;
insert into public.budget_periods(id,profile_id,starts_on,ends_on,base_currency)
values(pg_temp.id(20),'f0050000-0000-4000-8000-000000000002',pg_temp.month(-1),(pg_temp.month(-1)+interval '1 month -1 day')::date,'USD');
insert into public.budget_buckets(id,profile_id,name,type) values
(pg_temp.id(30),'f0050000-0000-4000-8000-000000000001','Needs','SPENDABLE'),
(pg_temp.id(31),'f0050000-0000-4000-8000-000000000001','Savings','SAVINGS');
insert into public.categories(id,profile_id,name,budget_bucket_id)
values(pg_temp.id(32),'f0050000-0000-4000-8000-000000000001','Food',pg_temp.id(30));
create function pg_temp.context(n integer) returns jsonb language sql stable as $$select public.get_personal_period_close_context(pg_temp.month(n))$$;
create function pg_temp.close(n integer,request uuid default gen_random_uuid(),version bigint default 0,fingerprint text default null,confirmed boolean default true)
returns jsonb language sql volatile as $$select public.close_personal_budget_period(request,pg_temp.id(n+10),version,coalesce(fingerprint,pg_temp.context(n)->>'snapshot_hash'),confirmed)$$;
select ok((select relrowsecurity from pg_class where oid='public.budget_period_closures'::regclass),'Close evidence uses RLS');
select ok(not has_table_privilege('authenticated','public.budget_period_closures',p),'No client evidence '||p) from unnest(array['INSERT','UPDATE','DELETE','TRUNCATE','TRIGGER']) p;
select ok(not has_column_privilege('authenticated','public.budget_periods',c,'UPDATE'),'No client lifecycle update: '||c) from unnest(array['status','closed_at','lifecycle_version']) c;
select ok(not has_column_privilege('authenticated','public.budget_periods','lifecycle_version','INSERT'),'Cannot forge initial lifecycle');
select is(prosecdef,true,'Close definer is explicit') from pg_proc where oid='public.close_personal_budget_period(uuid,uuid,bigint,text,boolean)'::regprocedure;
select is(prosecdef,false,'Preview remains invoker') from pg_proc where oid='public.get_personal_period_close_context(date)'::regprocedure;
select ok(proconfig @> array['search_path=""'],'Empty path: '||proname) from pg_proc where oid in ('public.close_personal_budget_period(uuid,uuid,bigint,text,boolean)'::regprocedure,'public.get_personal_period_close_context(date)'::regprocedure);
select ok(not has_function_privilege('anon',f,'EXECUTE'),'Anonymous lacks '||f) from unnest(array['public.close_personal_budget_period(uuid,uuid,bigint,text,boolean)','public.get_personal_period_close_context(date)']) f;
set local role authenticated;
select pg_temp.set_jwt_subject('f0050000-0000-4000-8000-000000000001');
select is(current_user::text,'authenticated','Owner role');
select is(auth.uid(),'f0050000-0000-4000-8000-000000000001'::uuid,'Owner identity');
select is(pg_temp.context(-1)->>'financial_month',pg_temp.month()::text,'Eligibility uses persisted financial timezone on server');
select is(pg_temp.context(-1)->>'financial_timezone','Pacific/Kiritimati','Server timezone shown');
select is(pg_temp.context(-1)->>'snapshot_hash',pg_temp.context(-1)->>'snapshot_hash','Repeated preview deterministic');
select is(pg_temp.context(0)->>'can_close','false','Current month incomplete');
select is(pg_temp.context(1)->>'can_close','false','Future month incomplete');
select throws_ok($$select pg_temp.close(0)$$,'23514',null,'Cannot close current month even with client confirmation');
select throws_ok($$select pg_temp.close(1)$$,'23514',null,'Cannot close future month');
select throws_ok($$select pg_temp.close(-1,gen_random_uuid(),0,null,false)$$,'22023',null,'Explicit true confirmation required');
select throws_ok($$select pg_temp.close(-1,gen_random_uuid(),0,null,null)$$,'22023',null,'Null confirmation rejected');
select throws_ok($$select pg_temp.close(-1,gen_random_uuid(),-1)$$,'22023',null,'Invalid lifecycle rejected');
select throws_ok($$select pg_temp.close(-1,gen_random_uuid(),1)$$,'40001',null,'Wrong expected lifecycle conflicts');
select throws_ok($$select pg_temp.close(-1,gen_random_uuid(),0,'not-a-hash')$$,'22023',null,'Invalid fingerprint rejected');
select throws_ok($$select public.get_personal_period_close_context(pg_temp.month()+1)$$,'22023',null,'Noncanonical month rejected');
select ok((public.get_personal_period_close_context(pg_temp.month(-20))->>'period') is null,'Absent period is explicit');
select public.save_budget_allocations(id,jsonb_build_array(jsonb_build_object('budget_bucket_id',pg_temp.id(30),'percentage_basis_points',8000),jsonb_build_object('budget_bucket_id',pg_temp.id(31),'percentage_basis_points',2000))) from public.budget_periods where id in(pg_temp.id(8),pg_temp.id(9));
select public.register_income(pg_temp.id(40),pg_temp.id(8),1000,'USD',pg_temp.month(-2));
select public.register_income(pg_temp.id(41),pg_temp.id(9),1000,'USD',pg_temp.month(-1));
select public.register_personal_expense(pg_temp.id(42),pg_temp.id(9),900,'USD',pg_temp.month(-1),pg_temp.id(32));
select public.register_personal_expense(pg_temp.id(43),pg_temp.id(9),1,'USD',pg_temp.month(-1),pg_temp.id(32));
select public.correct_personal_transaction(pg_temp.id(44),pg_temp.id(43),0,'DELETE','{}',true);
select set_config('fin123.old_hash',pg_temp.context(-1)->>'snapshot_hash',true);
update public.transactions set description='Meaningful reviewed change' where id=pg_temp.id(42);
-- A note is not in the aggregate, so it correctly does not stale financial facts.
select is(pg_temp.context(-1)->>'snapshot_hash',current_setting('fin123.old_hash'),'Nonfinancial note does not alter summary');
update public.budget_periods set expected_income_minor=2000 where id=pg_temp.id(9);
select throws_ok($$select pg_temp.close(-1,gen_random_uuid(),0,current_setting('fin123.old_hash'))$$,'40001',null,'Financial preview change requires review');
select set_config('fin123.close_hash',pg_temp.context(-1)->>'snapshot_hash',true);
select is(pg_temp.close(-1,pg_temp.id(50))->>'lifecycle_version','1','Completed month closes atomically');
select is((select status from public.budget_periods where id=pg_temp.id(9)),'CLOSED','Persisted CLOSED');
select is((select lifecycle_version from public.budget_periods where id=pg_temp.id(9)),1::bigint,'Lifecycle advances');
select ok((select closed_at is not null from public.budget_periods where id=pg_temp.id(9)),'Timestamp recorded');
select is((select count(*) from public.transactions),4::bigint,'Close creates no transaction');
select is(pg_temp.context(-1)#>>'{summary,availability,savings,spent_minor}','900','Actual spend retained');
select is(pg_temp.context(-1)#>>'{summary,availability,savings,opening_protected_minor}','200','Cumulative opening captured as of close');
select is(pg_temp.context(-1)#>>'{summary,availability,savings,allocated_savings_minor}','200','Month savings allocation distinct');
select is(pg_temp.close(-1,pg_temp.id(50),0,current_setting('fin123.close_hash'))->>'lifecycle_version','1','Exact closed replay reads evidence');
select is((select count(*) from public.budget_period_closures),1::bigint,'Replay creates no extra close');
select throws_ok($$select pg_temp.close(-1,pg_temp.id(50),1,current_setting('fin123.close_hash'))$$,'23505',null,'Changed UUID payload conflicts');
select throws_ok($$select pg_temp.close(-1,gen_random_uuid(),0,current_setting('fin123.close_hash'))$$,'40001',null,'Another UUID cannot close closed month');
select throws_ok($$update public.budget_periods set status='OPEN',closed_at=null where id=pg_temp.id(9)$$,'42501',null,'Direct reopen forbidden');
select results_eq($$update public.budget_periods set expected_income_minor=4 where id=pg_temp.id(9) returning id$$,array[]::uuid[],'Closed metadata edit filtered by RLS');
select throws_ok($$select public.save_budget_allocations(pg_temp.id(9),jsonb_build_array(jsonb_build_object('budget_bucket_id',pg_temp.id(30),'percentage_basis_points',10000)))$$,'42501',null,'Closed allocation replacement denied');
select throws_ok($$select public.register_income(gen_random_uuid(),pg_temp.id(9),1,'USD',pg_temp.month(-1))$$,'42501',null,'Closed income rejected');
select throws_ok($$select public.register_personal_expense(gen_random_uuid(),pg_temp.id(9),1,'USD',pg_temp.month(-1),pg_temp.id(32))$$,'42501',null,'Closed expense rejected');
select throws_ok($$select public.register_savings_movement(gen_random_uuid(),pg_temp.id(9),'SAVINGS_WITHDRAWAL',1,'USD',pg_temp.month(-1),true)$$,'42501',null,'Closed withdrawal rejected');
select throws_ok($$select public.correct_personal_transaction(gen_random_uuid(),pg_temp.id(41),0,'EDIT',jsonb_build_object('amount_minor',1100,'transaction_date',pg_temp.month(-1),'category_id',null,'description',null),true)$$,'42501',null,'Closed monetary correction rejected');
select throws_ok($$select public.correct_personal_transaction(gen_random_uuid(),pg_temp.id(43),1,'RESTORE','{}',true)$$,'42501',null,'Closed restoration rejected');
select results_eq($$update public.transactions set deleted_at=null where id=pg_temp.id(43) returning id$$,array[]::uuid[],'Direct restoration cannot bypass closed state');
select results_eq($$update public.transactions set description='No' where id=pg_temp.id(42) returning id$$,array[]::uuid[],'Direct closed note denied');
select throws_ok($$insert into public.budget_period_closures select * from public.budget_period_closures$$,'42501',null,'Cannot forge close evidence');
select throws_ok($$update public.budget_period_closures set summary='{}'$$,'42501',null,'Cannot rewrite evidence');
select throws_ok($$delete from public.budget_period_closures$$,'42501',null,'Cannot erase evidence');
select public.correct_personal_transaction(pg_temp.id(45),pg_temp.id(40),0,'EDIT',jsonb_build_object('amount_minor',2000,'transaction_date',pg_temp.month(-2),'category_id',null,'description',null),true);
select is(public.get_personal_dashboard(pg_temp.month(-1))#>>'{availability,savings,opening_protected_minor}','400','Explicit older correction changes live cumulative savings');
select is(pg_temp.context(-1)#>>'{summary,availability,savings,opening_protected_minor}','200','Immutable close retains as-of cumulative savings');
select is(pg_temp.context(-1)->>'snapshot_hash',current_setting('fin123.close_hash'),'Older correction never rewrites close fingerprint');
select is(pg_temp.close(-3)->>'lifecycle_version','1','Empty unconfigured completed month can close without inventing availability');
select is(pg_temp.context(-3)#>>'{summary,availability,savings,configured}','false','Unconfigured summary stays unconfigured');
-- Trusted simulation of FIN-124 ONLY in this rolled-back fixture, no reopen API.
set constraints all immediate;
reset role;
update public.budget_periods set status='OPEN',closed_at=null,lifecycle_version=2 where id=pg_temp.id(9);
set local role authenticated;
select pg_temp.set_jwt_subject('f0050000-0000-4000-8000-000000000001');
select is(current_user::text,'authenticated','Replay owner role');
select is(auth.uid(),'f0050000-0000-4000-8000-000000000001'::uuid,'Replay owner identity');
select is(pg_temp.close(-1,pg_temp.id(50),0,current_setting('fin123.close_hash'))->>'lifecycle_version','1','Old replay after lifecycle change returns original evidence');
select is((select status from public.budget_periods where id=pg_temp.id(9)),'OPEN','Old replay never re-closes later lifecycle');
select throws_ok($$select pg_temp.close(-1,gen_random_uuid(),0,current_setting('fin123.close_hash'))$$,'40001',null,'Stale new close cannot close later lifecycle');
select is((select count(*) from public.budget_period_closures where budget_period_id=pg_temp.id(9)),1::bigint,'Previous evidence is retained');
reset role;
set local role authenticated;
select pg_temp.set_jwt_subject('f0050000-0000-4000-8000-000000000002');
select is(current_user::text,'authenticated','Partner role');
select is(auth.uid(),'f0050000-0000-4000-8000-000000000002'::uuid,'Partner identity');
select is((select count(*) from public.budget_period_closures),0::bigint,'Partner cannot read private close evidence');
select throws_ok($$select public.close_personal_budget_period(pg_temp.id(50),pg_temp.id(9),0,repeat('a',32),true)$$,'42501',null,'Partner cannot replay another owner close');
select is(pg_temp.context(-1)#>>'{period,id}',pg_temp.id(20)::text,'Partner preview only resolves own month');
reset role;
set local role authenticated;
select pg_temp.set_jwt_subject('f0050000-0000-4000-8000-000000000003');
select is(current_user::text,'authenticated','Stranger role');
select is(auth.uid(),'f0050000-0000-4000-8000-000000000003'::uuid,'Stranger identity');
select is((select count(*) from public.budget_period_closures),0::bigint,'Stranger cannot read private close evidence');
select throws_ok($$select public.close_personal_budget_period(gen_random_uuid(),pg_temp.id(9),0,repeat('a',32),true)$$,'42501',null,'Stranger cannot close another owner period');
select ok((pg_temp.context(-1)->>'period') is null,'Stranger gets no private preview');
select pg_temp.set_jwt_subject(null);
select is(auth.uid(),null::uuid,'Cleared identity');
select throws_ok($$select public.close_personal_budget_period(gen_random_uuid(),pg_temp.id(9),0,repeat('a',32),true)$$,'42501',null,'Null subject cannot use definer');
select throws_ok($$select pg_temp.context(-1)$$,'42501',null,'Null subject cannot preview');
reset role;
set local role anon;
select pg_temp.set_jwt_subject(null);
select is(current_user::text,'anon','Anonymous role');
select is(auth.uid(),null::uuid,'Anonymous identity');
select throws_ok($$select * from public.budget_period_closures$$,'42501',null,'Anonymous table read denied');
select throws_ok($$select pg_temp.context(-1)$$,'42501',null,'Anonymous preview denied');
select throws_ok($$select public.close_personal_budget_period(gen_random_uuid(),pg_temp.id(9),0,repeat('a',32),true)$$,'42501',null,'Anonymous close denied');
reset role;
select * from finish();
rollback;
